-- Disposable local Postgres only, after installed prerequisite and group migrations.
\set ON_ERROR_STOP on
create or replace function pg_temp.assert(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERT: %',message; end if; end $$;
begin;
create temp table old_dm_policies as select * from pg_policies where tablename in('dm_conversations','dm_messages','profiles','user_courses','objects');
insert into auth.users(id,email,email_confirmed_at) select ('90000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'group'||n||'@stonybrook.edu',case when n=7 then null else now() end from generate_series(1,65)n;
insert into auth.identities select id,'google',jsonb_build_object('email',email,'email_verified',true) from auth.users where id::text like '90000000-%';
update public.profiles set name='Friend '||right(id::text,3),allow_new_dms=(id<>'90000000-0000-0000-0000-000000000006') where id::text like '90000000-%';
insert into public.friendships(user_id,friend_id) select '90000000-0000-0000-0000-000000000001',id from auth.users where id::text like '90000000-%' and right(id::text,12)::int between 2 and 64;
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select pg_temp.assert(jsonb_array_length(public.group_friend_candidates())=50,'friend first page bounded');
select set_config('test.friend_last',(public.group_friend_candidates()->49)::text,true);
select pg_temp.assert(jsonb_array_length(public.group_friend_candidates(null,'',current_setting('test.friend_last')::jsonb->>'name',(current_setting('test.friend_last')::jsonb->>'student_id')::uuid))=13,'all friends reachable without courses');
select pg_temp.assert(public.group_friend_candidates(null,'Friend 006')->0->>'reason'='closed','closed friend disabled');
select pg_temp.assert(public.group_friend_candidates(null,'Friend 007')->0->>'reason'='unavailable','ineligible friend disabled');
do $$ begin
 begin perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid],gen_random_uuid());raise exception 'too small';exception when invalid_parameter_value then null;end;
 begin perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000002'::uuid],gen_random_uuid());raise exception 'duplicate';exception when invalid_parameter_value then null;end;
 begin perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000065'::uuid],gen_random_uuid());raise exception 'unrelated';exception when insufficient_privilege then null;end;
 begin perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000006'::uuid],gen_random_uuid());raise exception 'closed';exception when raise_exception then if sqlerrm not like 'New messages%' then raise;end if;end;
end $$;
do $$ begin
 begin perform public.group_create(array[auth.uid(),'90000000-0000-0000-0000-000000000002'::uuid],gen_random_uuid());raise exception 'self selection';exception when invalid_parameter_value then null;end;
 begin perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000003'::uuid],gen_random_uuid(),repeat('😀',81));raise exception 'name limit';exception when invalid_parameter_value then null;end;
end $$;
select pg_temp.assert((select count(*)=0 from public.group_conversations),'failed creates atomic');
select set_config('test.group_request',gen_random_uuid()::text,true);
select set_config('test.group_id',public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000003'::uuid],current_setting('test.group_request')::uuid,' Our group ')->>'group_id',true);
select pg_temp.assert(public.group_detail(current_setting('test.group_id')::uuid)->>'name'='Our group','trimmed name');
select pg_temp.assert(jsonb_array_length(public.group_detail(current_setting('test.group_id')::uuid)->'members')=3,'three members');
select pg_temp.assert(public.group_create(array['90000000-0000-0000-0000-000000000003'::uuid,'90000000-0000-0000-0000-000000000002'::uuid],current_setting('test.group_request')::uuid,'Our group')->>'group_id'=current_setting('test.group_id'),'canonical creation replay');
do $$ begin begin perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000003'::uuid],current_setting('test.group_request')::uuid,'Changed');raise exception 'collision';exception when unique_violation then null;end;end $$;
select pg_temp.assert((select count(*)=1 from public.group_conversations),'no duplicate group');
select pg_temp.assert((public.messaging_inbox()->0->>'preview') is null,'empty group included without preview');
select pg_temp.assert(public.messaging_unread()='[]','empty group no unread');
select set_config('test.send_request',gen_random_uuid()::text,true);
select public.group_send_message(current_setting('test.group_id')::uuid,E'<b>literal</b>\n😀',current_setting('test.send_request')::uuid);
select public.group_send_message(current_setting('test.group_id')::uuid,E'<b>literal</b>\n😀',current_setting('test.send_request')::uuid);
select pg_temp.assert((select last_sequence=1 from public.group_conversations where id=current_setting('test.group_id')::uuid),'send replay one sequence');
do $$ begin
 begin perform public.group_send_message(current_setting('test.group_id')::uuid,'Changed',current_setting('test.send_request')::uuid);raise exception 'collision';exception when unique_violation then null;end;
 begin perform public.group_send_message(current_setting('test.group_id')::uuid,E'\n\t'||chr(65279),gen_random_uuid());raise exception 'whitespace';exception when invalid_parameter_value then null;end;
 begin perform public.group_send_message(current_setting('test.group_id')::uuid,repeat('😀',2001),gen_random_uuid());raise exception 'oversize';exception when invalid_parameter_value then null;end;
 begin insert into public.group_messages(group_id,sequence,sender_id,client_message_id,body) values(current_setting('test.group_id')::uuid,999,auth.uid(),gen_random_uuid(),'forged');raise exception 'direct write';exception when insufficient_privilege then null;end;
 begin perform * from public.group_members;raise exception 'read positions leaked';exception when insufficient_privilege then null;end;
end $$;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select pg_temp.assert((public.messaging_unread()->0->>'count')::int=1,'recipient unread');
select public.group_mark_read(current_setting('test.group_id')::uuid,1);
select pg_temp.assert(public.messaging_unread()='[]','read clears own count');
do $$ begin begin perform public.group_add_members(current_setting('test.group_id')::uuid,array['90000000-0000-0000-0000-000000000004'::uuid],gen_random_uuid());raise exception 'noncreator add';exception when insufficient_privilege then null;end;end $$;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
select set_config('test.add_request',gen_random_uuid()::text,true);
select public.group_add_members(current_setting('test.group_id')::uuid,array['90000000-0000-0000-0000-000000000004'::uuid],current_setting('test.add_request')::uuid);
select public.group_add_members(current_setting('test.group_id')::uuid,array['90000000-0000-0000-0000-000000000004'::uuid],current_setting('test.add_request')::uuid);
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000004',true);
select pg_temp.assert(public.group_history(current_setting('test.group_id')::uuid)='[]','new member no old history');
select pg_temp.assert((select count(*)=0 from public.group_messages),'RLS no old rows');
select pg_temp.assert(public.messaging_unread()='[]','no prejoin unread');
select pg_temp.assert((public.messaging_inbox()->0->>'preview') is null,'no prejoin preview');
do $$ begin begin perform public.group_history(current_setting('test.group_id')::uuid,null,0);raise exception 'prejoin after cursor';exception when invalid_parameter_value then null;end;end $$;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select public.group_send_message(current_setting('test.group_id')::uuid,'Post join',gen_random_uuid());
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000004',true);
select pg_temp.assert(jsonb_array_length(public.group_history(current_setting('test.group_id')::uuid))=1,'postjoin visible');
do $$ begin
 begin perform public.group_history(current_setting('test.group_id')::uuid,1);raise exception 'prejoin before';exception when invalid_parameter_value then null;end;
 begin perform public.group_history(current_setting('test.group_id')::uuid,null,9999);raise exception 'future cursor';exception when invalid_parameter_value then null;end;
 begin perform public.group_history(current_setting('test.group_id')::uuid,2,2);raise exception 'conflicting cursor';exception when invalid_parameter_value then null;end;
 begin perform public.group_mark_read(current_setting('test.group_id')::uuid,9999);raise exception 'future read';exception when invalid_parameter_value then null;end;
end $$;
select public.group_mark_read(current_setting('test.group_id')::uuid,2);
select public.group_mark_read(current_setting('test.group_id')::uuid,2);
select pg_temp.assert(public.messaging_unread()='[]','read replay stable');
reset role;
update public.profiles set allow_new_dms=false where id='90000000-0000-0000-0000-000000000004';
delete from public.friendships where user_id='90000000-0000-0000-0000-000000000001' and friend_id='90000000-0000-0000-0000-000000000004';
set local role authenticated;
select public.group_send_message(current_setting('test.group_id')::uuid,'Existing continues',gen_random_uuid());
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000001',true);
do $$ begin for n in 1..70 loop perform public.group_send_message(current_setting('test.group_id')::uuid,'Page '||n,gen_random_uuid());end loop;end $$;
select pg_temp.assert(jsonb_array_length(public.group_history(current_setting('test.group_id')::uuid))=50,'latest page bounded');
select pg_temp.assert(jsonb_array_length(public.group_history(current_setting('test.group_id')::uuid,24))=23,'older history reachable');
select pg_temp.assert(jsonb_array_length(public.group_history(current_setting('test.group_id')::uuid,null,0))=50,'catchup first page bounded');
select pg_temp.assert(jsonb_array_length(public.group_history(current_setting('test.group_id')::uuid,null,50))=23,'catchup rest');
do $$ begin for n in 1..55 loop perform public.group_create(array['90000000-0000-0000-0000-000000000002'::uuid,'90000000-0000-0000-0000-000000000003'::uuid],gen_random_uuid());end loop;end $$;
select public.dm_send_message('90000000-0000-0000-0000-000000000002','Direct alongside groups',gen_random_uuid());
select pg_temp.assert(jsonb_array_length(public.messaging_inbox())=50,'inbox bounded');
select set_config('test.inbox_last',(public.messaging_inbox()->49)::text,true);
select pg_temp.assert(jsonb_array_length(public.messaging_inbox((current_setting('test.inbox_last')::jsonb->>'last_message_at')::timestamptz,current_setting('test.inbox_last')::jsonb->>'kind',(current_setting('test.inbox_last')::jsonb->>'conversation_id')::uuid))=7,'inbox older all reachable');
-- Initial capacity and fully atomic invalid batches.
do $$ declare ids uuid[]; begin
 select array_agg(('90000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid) into ids from generate_series(2,51)n;
 begin perform public.group_create(ids,gen_random_uuid());raise exception 'oversized creation';exception when invalid_parameter_value then null;end;
 begin perform public.group_add_members(current_setting('test.group_id')::uuid,array['90000000-0000-0000-0000-000000000005'::uuid,'90000000-0000-0000-0000-000000000006'::uuid],gen_random_uuid());raise exception 'partial closed batch';exception when raise_exception then if sqlerrm not like 'New messages%' then raise;end if;end;
end $$;
reset role;
select pg_temp.assert(not exists(select 1 from public.group_members where group_id=current_setting('test.group_id')::uuid and user_id='90000000-0000-0000-0000-000000000005'),'no partial batch member');
update auth.users set email_confirmed_at=null where id='90000000-0000-0000-0000-000000000003';
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000003',true);
do $$ begin begin perform public.group_history(current_setting('test.group_id')::uuid);raise exception 'ineligible group history';exception when insufficient_privilege then null;end;end $$;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select pg_temp.assert(jsonb_array_length(public.messaging_unread())=2,'separate group and direct unread counts');
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000065',true);
select pg_temp.assert((select count(*)=0 from public.group_conversations),'outsider RLS');
select pg_temp.assert(public.messaging_unread()='[]','outsider counts private');
do $$ begin
 begin perform public.group_detail(current_setting('test.group_id')::uuid);raise exception 'outsider detail';exception when insufficient_privilege then null;end;
 begin perform public.group_send_message(current_setting('test.group_id')::uuid,'forged',gen_random_uuid());raise exception 'outsider send';exception when insufficient_privilege then null;end;
end $$;
reset role;
-- Delete a creator/sender: remaining group persists and nobody gains creator authority.
delete from auth.identities where user_id='90000000-0000-0000-0000-000000000001';
delete from auth.users where id='90000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','90000000-0000-0000-0000-000000000002',true);
select pg_temp.assert(public.group_detail(current_setting('test.group_id')::uuid)->>'creator_id' is null,'creator deletion nulls ownership');
select pg_temp.assert(jsonb_array_length(public.group_history(current_setting('test.group_id')::uuid))=50,'history preserved after sender deletion');
select public.group_send_message(current_setting('test.group_id')::uuid,'Still here',gen_random_uuid());
reset role;
set local role anon;
do $$ begin begin perform public.messaging_inbox();raise exception 'anon';exception when insufficient_privilege then null;end;end $$;
reset role;
select pg_temp.assert(not exists((select * from old_dm_policies except select * from pg_policies where tablename in('dm_conversations','dm_messages','profiles','user_courses','objects'))),'old policies intact');
rollback;
